import{_ as a,a0 as r,w as l,s as d,I as n,x as o,a1 as p,A as e,ao as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"在 Linux 上安裝安卓 8.1 Oreo 來運行應用程序和遊戲 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上安裝安卓 8.1 Oreo 來運行應用程序和遊戲 | LCTT (201912) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上安裝安卓 8.1 Oreo 來運行應用程序和遊戲 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上安裝安卓 8.1 Oreo 來運行應用程序和遊戲 | LCTT (201912) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201912/20190217 Install Android 8.1 Oreo on Linux To Run Apps - Games","title":"在 Linux 上安裝安卓 8.1 Oreo 來運行應用程序和遊戲","tag":"201912","desc":""},"relativePath":"201912/20190217 Install Android 8.1 Oreo on Linux To Run Apps - Games.md","filePath":"[post].md"}'),u={name:"201912/20190217 Install Android 8.1 Oreo on Linux To Run Apps - Games.md"};function m(g,s,h,x,b,k){const i=r("Link");return l(),d("div",null,[s[25]||(s[25]=n("h1",{id:"在-linux-上安裝安卓-8-1-oreo-來運行應用程序和遊戲",tabindex:"-1"},[o("在 Linux 上安裝安卓 8.1 Oreo 來運行應用程序和遊戲 "),n("a",{class:"header-anchor",href:"#在-linux-上安裝安卓-8-1-oreo-來運行應用程序和遊戲","aria-label":"Permalink to “在 Linux 上安裝安卓 8.1 Oreo 來運行應用程序和遊戲”"},"​")],-1)),s[26]||(s[26]=n("p",null,[n("img",{src:"https://i2.wp.com/fosspost.org/wp-content/uploads/2019/02/android-8.1-oreo-x86-on-linux.png?resize=1237%2C527&ssl=1",alt:""})],-1)),n("p",null,[p(i,{href:"http://www.android-x86.org/"},{default:e(()=>[...s[0]||(s[0]=[o("android x86",-1)])]),_:1}),s[1]||(s[1]=o(" 是一個自由而開源的項目，將谷歌製作的安卓系統從 ARM 架構移植到了 x86 架構，可以讓用户在他們的桌面電腦上運行安卓系統來享受所有的安卓功能和應用程序及遊戲。",-1))]),s[27]||(s[27]=n("p",null,"在前一段時間，android x86 項目完成了安卓 8.1 Oreo 系統的 x86 架構移植。在這篇文章中，我們將解釋如何在你的 Linux 系統上安裝它，以便你能夠隨時使用你的安卓 用程序和遊戲。",-1)),s[28]||(s[28]=n("h3",{id:"在-linux-上安裝安卓-x86-8-1-oreo",tabindex:"-1"},[o("在 Linux 上安裝安卓 x86 8.1 Oreo "),n("a",{class:"header-anchor",href:"#在-linux-上安裝安卓-x86-8-1-oreo","aria-label":"Permalink to “在 Linux 上安裝安卓 x86 8.1 Oreo”"},"​")],-1)),s[29]||(s[29]=n("h4",{id:"準備環境",tabindex:"-1"},[o("準備環境 "),n("a",{class:"header-anchor",href:"#準備環境","aria-label":"Permalink to “準備環境”"},"​")],-1)),n("p",null,[s[3]||(s[3]=o("首先，讓我們下載 android x86 8.1 Oreo 系統鏡像。你可以從",-1)),p(i,{href:"http://www.android-x86.org/download"},{default:e(()=>[...s[2]||(s[2]=[o("這個頁面",-1)])]),_:1}),s[4]||(s[4]=o("下載它，只需單擊 “android-x86_64-8.1-r1.iso” 文件下的 “View” 按鈕。",-1))]),s[30]||(s[30]=t('<p>我們將在我們的 Linux 系統上使用 QEMU 來運行 android x86。QEMU 是一個非常好的模擬器軟件，它也是自由而開源的，並且在所有主要的 Linux 發行版存儲庫中都是可用的。</p><p>在 Ubuntu/Linux Mint/Debian 上安裝 QEMU：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install qemu qemu-kvm libvirt-bin</span></span></code></pre></div><p>在 Fedora 上安裝 QEMU：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install qemu qemu-kvm</span></span></code></pre></div><p>對於其它發行版，只需要搜索 “qemu” 和 “qemu-kvm” 軟件包，並安裝它們。</p><p>在你安裝 QEMU 後，我們將需要運行下面的命令來創建 <code>android.img</code> 文件，它就像某種分配給安卓系統的磁盤空間。所有安卓文件和系統都將位於該鏡像文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>qemu-img create -f qcow2 android.img 15G</span></span></code></pre></div><p>我們在這裏的意思是，我們想為該安卓系統分配一個最大 15GB 的磁盤空間，但是，你可以更改它到你想要的任意大小（確保它至少大於 5GB）。</p><p>現在，首次啓動運行該安卓系統，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo qemu-system-x86_64 -m 2048 -boot d -enable-kvm -smp 3 -net nic -net user -hda android.img -cdrom /home/mhsabbagh/android-x86_64-8.1-r1.iso</span></span></code></pre></div>',11)),n("p",null,[s[6]||(s[6]=o("將 ",-1)),s[7]||(s[7]=n("code",null,"/home/mhsabbagh/android-x86_64-8.1-r1.iso",-1)),s[8]||(s[8]=o(" 替換為你從 android x86 網站下載的文件的路徑。關於我們在這裏正在使用的其它選項的解釋，你可以參考",-1)),p(i,{href:"https://fosspost.org/tutorials/use-qemu-test-operating-systems-distributions"},{default:e(()=>[...s[5]||(s[5]=[o("這篇文章",-1)])]),_:1}),s[9]||(s[9]=o("。",-1))]),s[31]||(s[31]=t(`<p>在你運行上面的命令後，該安卓系統將啓動：</p><p><img src="https://i0.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-16.png?resize=694%2C548&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 40 android 8.1 oreo on linux"></p><h4 id="安裝系統" tabindex="-1">安裝系統 <a class="header-anchor" href="#安裝系統" aria-label="Permalink to “安裝系統”">​</a></h4><p>從這個窗口中，選擇 “Advanced options”, 它將引導到下面的菜單，你應如下在其中選擇 “Auto_installation” ：</p><p><img src="https://i0.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-15.png?resize=673%2C537&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 42 android 8.1 oreo on linux"></p><p>在這以後，安裝器將告知你是否想要繼續，選擇 “Yes”：</p><p><img src="https://i1.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-14.png?resize=769%2C469&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 44 android 8.1 oreo on linux"></p><p>接下來，安裝器將無需你的指示而繼續進行：</p><p><img src="https://i1.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-13.png?resize=767%2C466&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 46 android 8.1 oreo on linux"></p><p>最後，你將收到這個信息，它表示你已經成功安裝安卓 8.1 ：</p><p><img src="https://i0.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-12.png?resize=750%2C460&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 48 android 8.1 oreo on linux"></p><p>現在，關閉 QEMU 窗口即可。</p><h4 id="啓動和使用-安卓-8-1-oreo" tabindex="-1">啓動和使用 安卓 8.1 Oreo <a class="header-anchor" href="#啓動和使用-安卓-8-1-oreo" aria-label="Permalink to “啓動和使用 安卓 8.1 Oreo”">​</a></h4><p>現在，安卓系統已經完全安裝在你的 <code>android.img</code> 文件中，你應該使用下面的 QEMU 命令來啓動它，而不是前面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo qemu-system-x86_64 -m 2048 -boot d -enable-kvm -smp 3 -net nic -net user -hda android.img</span></span></code></pre></div><p>注意，我們所做的只是移除 <code>-cdrom</code> 選項及其參數。這是告訴 QEMU，我們不再想從我們下載的 ISO 文件啓動，相反，從這個安裝的安卓系統啓動。</p><p>你現在能夠看到安卓的啓動菜單：</p><p><img src="https://i1.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-11.png?resize=754%2C456&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 50 android 8.1 oreo on linux"></p><p>然後，你將進入第一個準備嚮導，選擇你的語言並繼續：</p><p><img src="https://i0.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-10.png?resize=850%2C559&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 52 android 8.1 oreo on linux"></p><p>從這裏，選擇 “Set up as new” 選項：</p><p><img src="https://i0.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-09.png?resize=850%2C569&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 54 android 8.1 oreo on linux"></p><p>然後，安卓將詢問你是否想登錄到你當前的谷歌賬號。這步驟是可選的，但是這很重要，以便你隨後可以使用谷歌 Play 商店：</p><p><img src="https://i1.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-08.png?resize=850%2C562&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 56 android 8.1 oreo on linux"></p><p>然後，你將需要接受條款：</p><p><img src="https://i2.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-07-1.png?resize=850%2C561&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 58 android 8.1 oreo on linux"></p><p>現在，你可以選擇你當前的時區：</p><p><img src="https://i0.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-06.png?resize=850%2C569&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 60 android 8.1 oreo on linux"></p><p>系統將詢問你是否想啓動一些數據收集功能。如果我是你的話，我將簡單地全部關閉它們，像這樣：</p><p><img src="https://i1.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-05.png?resize=850%2C559&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 62 android 8.1 oreo on linux"></p><p>最後，你將有兩種啓動類型可供選擇，我建議你選擇 Launcher3 選項，並使其成為默認項：</p><p><img src="https://i1.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-04.png?resize=850%2C553&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 64 android 8.1 oreo on linux"></p><p>然後，你將看到完整工作的安卓系統主屏幕：</p><p><img src="https://i0.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-03.png?resize=850%2C571&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 66 android 8.1 oreo on linux"></p><p>從現在起，你可以做你想做的任何事情；你可以使用內置的安卓應用程序，或者你可以瀏覽你的系統設置來根據你的喜好進行調整。你可以更改你的系統的外觀和體驗，或者你可以像示例一樣運行 Chrome ：</p><p><img src="https://i1.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-02.png?resize=850%2C555&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 68 android 8.1 oreo on linux"></p><p>你可以開始從谷歌 Play 商店安裝一些應用程序程序，像 WhatsApp 和其它的應用程序，以供你自己使用：</p><p><img src="https://i2.wp.com/fosspost.org/wp-content/uploads/2019/02/Android-8.1-Oreo-on-Linux-01.png?resize=850%2C557&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 70 android 8.1 oreo on linux"></p><p>你現在可以用你的系統做任何你想做的事。恭喜！</p><h3 id="以後如何輕鬆地運行安卓-8-1-oreo" tabindex="-1">以後如何輕鬆地運行安卓 8.1 Oreo <a class="header-anchor" href="#以後如何輕鬆地運行安卓-8-1-oreo" aria-label="Permalink to “以後如何輕鬆地運行安卓 8.1 Oreo”">​</a></h3><p>我們不想總是不得不打開終端窗口，並寫那些長長的 QEMU 命令來運行安卓系統，相反，我們想在我們需要時一次單擊就運行它。</p><p>為此，我們將使用下面的命令在 <code>/usr/share/applications</code> 下創建一個名為 <code>android.desktop</code> 的新文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nano /usr/share/applications/android.desktop</span></span></code></pre></div><p>並在其中粘貼下面的內容（右鍵單擊然後粘貼）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Desktop Entry]</span></span>
<span class="line"><span>Name=Android 8.1</span></span>
<span class="line"><span>Comment=Run Android 8.1 Oreo on Linux using QEMU</span></span>
<span class="line"><span>Icon=phone</span></span>
<span class="line"><span>Exec=bash -c &#39;pkexec env DISPLAY=$DISPLAY XAUTHORITY=$XAUTHORITY qemu-system-x86_64 -m 2048 -boot d -enable-kvm -smp 3 -net nic -net user -hda /home/mhsabbagh/android.img&#39;</span></span>
<span class="line"><span>Terminal=false</span></span>
<span class="line"><span>Type=Application</span></span>
<span class="line"><span>StartupNotify=true</span></span>
<span class="line"><span>Categories=GTK;</span></span></code></pre></div><p>再強調一次，你必需使用你係統上的本地鏡像路徑來替換 <code>/home/mhsabbagh/android.img</code> 。然後保存文件（<code>Ctrl+X</code>，然後按 <code>Y</code>，然後按回車）。</p><p>注意，我們需要使用 <code>pkexec</code> 來使用 root 權限運行 QEMU ，因為從較新的版本開始，普通用户不允許通過 libvirt 訪問 KVM 技術；這就是為什麼它將每次要求你輸入 root 密碼的原因。</p><p>現在，你將在應用程序菜單中看到安卓圖標，你可以在你想使用安卓的任何時間來簡單地單擊該圖標，QEMU 程序將啓動：</p><p><img src="https://i0.wp.com/fosspost.org/wp-content/uploads/2019/02/Screenshot-at-2019-02-17-1539.png?resize=850%2C557&amp;ssl=1" alt="" title="Install Android 8.1 Oreo on Linux To Run Apps &amp; Games 72 android 8.1 oreo on linux"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>我們向你展示如何在你的 Linux 系統上安裝和運行安卓 8.1 Oreo 。從現在起，在沒有其它一些軟件的（像 Blutsticks 和類似的方法）的情況下，你可以更容易地完成基於安卓的任務。在這裏，你有一個完整工作和功能的安卓系統，你可以隨心所欲地操作它，如果一些東西出錯，你可以簡單地幹掉該鏡像文件，然後隨時再一次重新運行安裝程序。</p><p>你之前嘗試過 android x86 嗎？你的體驗如何？</p><hr>`,53)),n("p",null,[s[11]||(s[11]=o("via: ",-1)),p(i,{href:"https://fosspost.org/tutorials/install-android-8-1-oreo-on-linux"},{default:e(()=>[...s[10]||(s[10]=[o("https://fosspost.org/tutorials/install-android-8-1-oreo-on-linux",-1)])]),_:1})]),n("p",null,[s[16]||(s[16]=o("作者：",-1)),p(i,{href:"https://fosspost.org/author/mhsabbagh"},{default:e(()=>[...s[12]||(s[12]=[o("M.Hanny Sabbagh",-1)])]),_:1}),s[17]||(s[17]=o(" 選題：",-1)),p(i,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[13]||(s[13]=[o("lujun9972",-1)])]),_:1}),s[18]||(s[18]=o(" 譯者：",-1)),p(i,{href:"https://github.com/robsean"},{default:e(()=>[...s[14]||(s[14]=[o("robsean",-1)])]),_:1}),s[19]||(s[19]=o(" 校對：",-1)),p(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[15]||(s[15]=[o("wxy",-1)])]),_:1})]),n("p",null,[s[22]||(s[22]=o("本文由 ",-1)),p(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[20]||(s[20]=[o("LCTT",-1)])]),_:1}),s[23]||(s[23]=o(" 原創編譯，",-1)),p(i,{href:"https://linux.cn/"},{default:e(()=>[...s[21]||(s[21]=[o("Linux中國",-1)])]),_:1}),s[24]||(s[24]=o(" 榮譽推出",-1))])])}const L=a(u,[["render",m]]);export{c as __pageData,L as default};
